contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user) public {
        require(user != address(this), "test contract must remain token-free");

        uint balanceBefore = c.tokenBalance(address(this));
        require(balanceBefore == 0, "fresh c must start with zero balance for this test contract");

        uint userBefore = c.tokenBalance(user);

        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = c.tokenBalance(address(this));
        uint userAfter = c.tokenBalance(user);

        if (reverted) {
            assert(balanceAfter == balanceBefore);
        } else {
            assert(balanceAfter == balanceBefore + 20);
        }

        if (user == address(this)) {
            assert(userAfter == userBefore);
        } else {
            assert(userAfter == userBefore);
        }
    }
}

