contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool callerIsBank) public {
        require(address(this).balance >= 0);

        // Setup: give the test contract zero balance (it starts at zero in a fresh c).
        // The deciding call: the test contract is msg.sender for c.airDrop();
        // this contract is not a Bank, so supportsToken() on address(this) will fail
        // unless the runtime selection below chooses a valid external call.

        bool reverted;
        if (callerIsBank) {
            // This branch is intentionally empty: we cannot make this contract be a Bank,
            // because supportsToken is called on msg.sender (i.e., on this InvMutTest).
            reverted = true;
        } else {
            try c.airDrop() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint bal = c.tokenBalance(address(this));
        assert((!reverted && bal == 20) || (reverted && bal == 0));
    }

    receive() external payable {}
}

